From 59e6f3eb1b4e3bbef635fb27b25c1889d065d261 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:40:59 +0100
Subject: [PATCH] donationmessage: link to what past donations made possible

The yearly donation notification asked for money without showing what
it pays for. Add a link to KDE e.V.'s reports in its text, which opens
in the browser and leaves the notification up so you can still donate.

BUG: 492379
---
 donationmessage/donationmessage.cpp | 7 +++++--
 1 file changed, 5 insertions(+), 2 deletions(-)

diff --git a/donationmessage/donationmessage.cpp b/donationmessage/donationmessage.cpp
index 6799e12a2c..f84ca37aaa 100644
--- a/donationmessage/donationmessage.cpp
+++ b/donationmessage/donationmessage.cpp
@@ -32,6 +32,7 @@ static const QString LAST_DONATION_KEY_NAME = u"yearLastSuppressedOrDonated"_s;
 static const int SHOW_IN_MONTH = 12;
 static const int MIN_INSTALLED_DAYS_BEFORE_ASKING = 14;
 static const QUrl DONATION_URL = QUrl(u"https://kde.org/donate/?app=plasma-donation-request-notification"_s);
+static const QUrl REPORTS_URL = QUrl(u"https://ev.kde.org/reports/"_s);

 DonationMessage::DonationMessage(QObject *parent, const QList<QVariant> &)
     : KDEDModule(parent)
@@ -78,8 +79,10 @@ DonationMessage::DonationMessage(QObject *parent, const QList<QVariant> &)
     notification->setComponentName(u"donationmessage"_s);
     notification->setFlags(KNotification::NotificationFlag::Persistent);
     notification->setTitle(i18nc("@title of a system notification", "Donate to KDE"));
-    notification->setText(i18nc("@info body text of a system notification",
-                                "KDE needs your help! Donations fund development and infrastructure important for KDE's continued existence."));
+    notification->setText(i18nc("@info body text of a system notification; %1 is a URL",
+                                "KDE needs your help! Donations fund development and infrastructure important for KDE's continued existence. "
+                                "<a href=\"%1\">See what past donations made possible</a>",
+                                REPORTS_URL.toString()));

     const QString donateActionText = i18nc("@action:button Make a donation now; translate this in as short a form as possible", "Donate…");
     const QString dontShowAgainActionText = i18nc("@action:button don't donate this year; translate this in as short a form as possible", "No Thanks");
-- 
